mapper.select:
SELECT client_code AS clientCode, COUNT(1) AS callCount, SUM(CASE WHEN success = 1 THEN 1 ELSE 0 END) AS successCount FROM platform_api_access_stat WHERE called_at >= #{from} AND called_at < #{to}
AND client_code = #{clientCode}
GROUP BY client_code ORDER BY callCount DESC

SELECT s.region_id AS regionId,
       COALESCE(s.country_code, r.country_code) AS countryCode,
       COALESCE(s.region_level, r.level) AS level,
       r.name AS name,
       COUNT(1) AS callCount
FROM platform_api_access_stat s
LEFT JOIN geo_region r ON r.id = s.region_id
WHERE s.called_at >= #{from} AND s.called_at < #{to}
  AND s.region_id IS NOT NULL

    AND (
        s.country_code = #{countryCode}
        OR (s.country_code IS NULL AND r.country_code = #{countryCode})
    )


    AND (
        s.region_level = #{regionLevel}
        OR (s.region_level IS NULL AND r.level = #{regionLevel})
    )

GROUP BY s.region_id, COALESCE(s.country_code, r.country_code), COALESCE(s.region_level, r.level), r.name
ORDER BY callCount DESC
LIMIT #{limit}
